-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: ALTER TABLE email_reply_queue DROP COLUMN tier; ALTER TABLE email_reply_queue DROP COLUMN tier_reason; ALTER TABLE email_reply_queue DROP COLUMN draft_proposed; DELETE FROM analytics_metric_triggers WHERE metric_key = 'email_replies_untiered_7d'; DELETE FROM metric_registry WHERE metric = 'email_replies_untiered_7d'; DELETE FROM ops_config WHERE key = 'email_voice_learn_last'
-- EMAIL-VOICE-DRAFTER-1 (2026-10-12, agent_issues 2373, owner request; pillar personal; qnfo-email 2.8.0 and qnfo-fleet-dashboard
-- 1.33.0 in the same PR). Every escalated human thread gets a tier (1 NO REPLY, 2 AUTO-SEND, 3 OWNER SENDS), the reason, and the
-- draft the fleet proposed (draft_proposed) next to the text that was sent (draft_text), so the weekly learning job can read the
-- owner's edits. The metric counts escalated threads older than an hour with no tier: the drafter runs on every cron tick, so a
-- row without a tier after an hour means the drafter did not run or threw.
ALTER TABLE email_reply_queue ADD COLUMN tier TEXT;
ALTER TABLE email_reply_queue ADD COLUMN tier_reason TEXT;
ALTER TABLE email_reply_queue ADD COLUMN draft_proposed TEXT;
INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, baseline, target, owner, disposition_actor, refresh_cadence, warning_band, kill_band, last_value, last_refreshed, state, refresh_class) VALUES
 ('email_replies_untiered_7d', 'operational', 'target',
  'email_reply_queue rows with decision escalate, no sent_at, created in the last 7 days and older than 60 minutes whose tier is NULL (EMAIL-VOICE-DRAFTER-1: the drafter classes every escalated thread on the cron tick)',
  'qnfo-audit.email_reply_queue.tier; refreshed by the METRIC-REFRESH fleet task', 'unmeasured before 2026-10-12 (no tier column)', '0', 'qnfo-email', 'qnfo-email', 'hourly', '> 0', '> 3', NULL, NULL, 'REGISTERED', 'd1');
UPDATE fleet_tasks SET definition = json_insert(definition, '$.steps[#]', json('{"type": "sql", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM email_reply_queue WHERE decision = ''escalate'' AND sent_at IS NULL AND tier IS NULL AND created_at >= datetime(''now'', ''-7 days'') AND created_at < datetime(''now'', ''-60 minutes'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''email_replies_untiered_7d''"}'))
  WHERE name LIKE 'METRIC-REFRESH-1%' AND definition NOT LIKE '%email_replies_untiered_7d%';
INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'email_replies_untiered_7d', 'Email voice: an escalated human thread has waited an hour with no tier', 'registry', 'gt', 0, 2,
  'Pillar personal (EMAIL-VOICE-DRAFTER-1, agent_issues 2373). Read SELECT id, sender, subject, created_at, skip_reason FROM email_reply_queue WHERE decision = ''escalate'' AND sent_at IS NULL AND tier IS NULL ORDER BY id: each row is a human thread the drafter did not class. Causes in order: (1) qnfo-email scheduled() threw before tierReplyQueue (worker logs, console "voice"); (2) the AI binding or the DASH binding is missing on the live worker (deployment_history bindings_installed; the canonical deploy installs declared bindings); (3) the row''s email has status spam (then it is not the drafter''s). DoD: the metric reads 0 after the next tick.',
  'qnfo-email', 'agent_issues', 3, 1, 'EMAIL-VOICE-DRAFTER-1 (migrations/2026-10-12-41-email-voice-tiers.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers WHERE metric_key = 'email_replies_untiered_7d');
UPDATE remediation_contracts SET verify_transport = 'd1-query',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM email_reply_queue WHERE decision = ''escalate'' AND sent_at IS NULL AND tier IS NULL AND created_at >= ''2026-10-12 17:30:00'' AND created_at < datetime(''now'', ''-60 minutes'')) > 0 THEN ''an escalated thread older than an hour has no tier'' WHEN (SELECT COUNT(*) FROM email_reply_queue WHERE tier IN (''2'', ''3'') AND sent_at IS NOT NULL AND draft_proposed IS NOT NULL AND (SELECT 1 FROM email_reply_queue x WHERE x.tier = ''3'' AND x.sent_at IS NOT NULL AND x.decision = ''sent'' AND x.skip_reason LIKE ''%cleared for auto-send%'' LIMIT 1) IS NOT NULL) > 0 THEN ''a tier-3 row was sent through the auto path'' WHEN (SELECT COUNT(*) FROM email_reply_queue WHERE tier IS NOT NULL AND created_at >= ''2026-10-12 17:30:00'') < 10 THEN ''pending: '' || (SELECT COUNT(*) FROM email_reply_queue WHERE tier IS NOT NULL AND created_at >= ''2026-10-12 17:30:00'') || '' of the next 10 inbound human threads carry a tier'' ELSE ''ok'' END AS observed',
  attempts = 0, last_verdict = NULL, status = 'active', next_due_at = datetime('now')
  WHERE class = 'issue-2373';
